parameters.jsCode:
// n8n Function node code
// Input: items from Telegram node (each item has .json.message.caption and .json.message.photo[] possibly)
// Output: items where each item.json.parsed contains the normalized schema
//
// Schema produced:
// {
//   product_name: string|null,
//   product_category: string|null,
//   aspect_ratio: string,                 // normalized like "9:16" or default "9:16"
//   desired_length_seconds: number|null,  // integer seconds
//   target_audience: string,              // default provided below
//   brand_voice: string,                  // default provided below
//   language: string,                     // default provided below
//   image_file_id: string|null            // chosen best photo file_id if present
// }

const DEFAULTS = {
  target_audience: "women aged 20–45 who care about skincare, glow, and anti-aging",
  brand_voice: "elegant, trustworthy, science-backed, warm",
  language: "en",
  aspect_ratio: "9:16"
};

function normalizeKey(k) {
  if (!k) return "";
  return k.toLowerCase().replace(/[^a-z0-9\s]/g, "").trim();
}

function extractNumber(str) {
  if (!str) return null;
  const m = str.match(/(\d+(\.\d+)?)/);
  if (!m) return null;
  return Math.round(parseFloat(m[1]));
}

function chooseBestPhoto(photoArray) {
  if (!Array.isArray(photoArray) || photoArray.length === 0) return null;
  // Prefer largest by file_size, fallback to largest width*height
  let best = null;
  for (const p of photoArray) {
    if (!best) { best = p; continue; }
    if (p.file_size && best.file_size) {
      if (p.file_size > best.file_size) best = p;
      continue;
    }
    // fallback compare area
    const a = (p.width||0) * (p.height||0);
    const b = (best.width||0) * (best.height||0);
    if (a > b) best = p;
  }
  return best ? best.file_id : null;
}

return items.map(item => {
  const msg = (item.json && (item.json.message || item.json)) || {};
  const captionRaw = msg.caption || msg.text || "";
  const lines = captionRaw.split(/\r?\n/).map(l => l.trim()).filter(l => l.length > 0);

  // initialize parsed values
  let product_name = null;
  let product_category = null;
  let aspect_ratio = null;
  let desired_length_seconds = null;

  // Try to parse key:value pairs first
  for (const line of lines) {
    // allow separators like ":" or "-" or "—"
    const parts = line.split(/[:\-–—]+/).map(p => p.trim());
    if (parts.length >= 2) {
      const rawKey = normalizeKey(parts[0]);
      const rest = parts.slice(1).join(":").trim();

      if (rawKey.includes("product") || rawKey.includes("name")) {
        // e.g., "Product name: Hex"
        product_name = rest || product_name;
        continue;
      }
      if (rawKey.includes("category") || rawKey.includes("cate") || rawKey.includes("type")) {
        product_category = rest || product_category;
        continue;
      }
      if (rawKey.includes("aspect") || rawKey.includes("ratio") || rawKey.includes("aspectration") || rawKey.includes("aspectration")) {
        // normalize common mistakes like "Aspect ration"
        const r = rest.replace(/\s+/g, "");
        if (/^\d+:\d+$/.test(r)) aspect_ratio = r;
        else aspect_ratio = rest || aspect_ratio;
        continue;
      }
      if (rawKey.includes("length") || rawKey.includes("sec") || rawKey.includes("seconds") || rawKey.includes("duration")) {
        const n = extractNumber(rest);
        if (n !== null) desired_length_seconds = n;
        continue;
      }
      // fallback heuristics
    } else {
      // lines without colon: try to infer
      const lower = line.toLowerCase();
      // e.g., "Length 10 sec" or "Aspect ration 9:16" possibly no colon
      if (lower.match(/\b(length|duration)\b/)) {
        const n = extractNumber(line);
        if (n !== null) desired_length_seconds = n;
        continue;
      }
      if (lower.match(/\b\d+:\d+\b/)) {
        const r = lower.match(/\b\d+:\d+\b/)[0];
        aspect_ratio = r;
        continue;
      }
    }

    // Additional tolerant patterns: e.g., "Cateory: Face Serum" (misspelling)
    const normalized = normalizeKey(line);
    if (normalized.includes("cateory") || normalized.includes("cate") && line.toLowerCase().includes("serum")) {
      // Attempt to extract value after last space
      const maybe = line.split(/[:\-]+/).slice(1).join(":").trim();
      if (maybe) product_category = maybe;
    }
  }

  // Extra pass: if some fields still missing, attempt regex captures in whole caption
  if (!product_name) {
    const m = captionRaw.match(/product\s*(?:name)?\s*[:\-–—]?\s*([^\n\r]+)/i);
    if (m) product_name = m[1].trim();
  }
  if (!product_category) {
    const m2 = captionRaw.match(/category|cateog?ry|cateory\s*[:\-–—]?\s*([^\n\r]+)/i);
    if (m2) product_category = m2[1].trim();
    else {
      // try "Face Serum" style detection (common product category words)
      const catMatch = captionRaw.match(/\b(serum|cleanser|moisturizer|toner|lotion|cream|oil)\b/i);
      if (catMatch) product_category = (product_category || (catMatch[0].toLowerCase() === "serum" ? "Face Serum" : catMatch[0]));
    }
  }
  if (!aspect_ratio) {
    const m3 = captionRaw.match(/\b(\d{1,2}:\d{1,2})\b/);
    if (m3) aspect_ratio = m3[1];
  }
  if (!desired_length_seconds) {
    const m4 = captionRaw.match(/(\d+)\s*(?:sec|seconds|s)\b/i);
    if (m4) desired_length_seconds = parseInt(m4[1], 10);
  }

  // Final normalization / fallbacks
  if (!aspect_ratio) aspect_ratio = DEFAULTS.aspect_ratio;
  // ensure aspect_ratio formats like "9:16" not "9x16" etc.
  aspect_ratio = aspect_ratio.toString().replace(/\s*x\s*/i, ":").trim();

  // If length is short and units possibly in "10 sec" -> keep as seconds; if minutes detected, convert (rare)
  if (desired_length_seconds === null) {
    // try minutes
    const mMin = captionRaw.match(/(\d+)\s*(?:min|minutes)\b/i);
    if (mMin) desired_length_seconds = parseInt(mMin[1], 10) * 60;
  }

  // pick best image file_id if photos exist
  const image_file_id = chooseBestPhoto((msg.photo || []));

  // Build parsed schema
  const parsed = {
    product_name: product_name ? product_name : null,
    product_category: product_category ? product_category : null,
    aspect_ratio: aspect_ratio || DEFAULTS.aspect_ratio,
    desired_length_seconds: desired_length_seconds !== null ? desired_length_seconds : null,
    target_audience: DEFAULTS.target_audience,
    brand_voice: DEFAULTS.brand_voice,
    language: DEFAULTS.language,
    image_file_id: image_file_id
  };

  // attach parsed object to the output item
  item.json.parsed = parsed;

  // also keep original caption for reference
  item.json._original_caption = captionRaw;

  return item;
});

